"""Production stager fixtures. Generated bytes only; no original staging."""
from email.message import Message
import hashlib
import importlib.util
import io
import json
from pathlib import Path
from types import SimpleNamespace

import pytest

SPEC=importlib.util.spec_from_file_location('stage186',Path(__file__).parents[1]/'environment'/'stage_data.py')
m=importlib.util.module_from_spec(SPEC);SPEC.loader.exec_module(m)


def row(name,payload=b'abc'):
    git=hashlib.sha1(b'blob '+str(len(payload)).encode()+b'\0'+payload).hexdigest()
    r=dict(path=name,role='events',size_bytes=len(payload),sha256=hashlib.sha256(payload).hexdigest(),md5=None,
        source_commit=m.DS_COMMIT,identity_kind='git_blob_content',content_git_blob_sha1=git)
    r['url']=m.expected_url(r);return r


@pytest.fixture
def manufactured(tmp_path,monkeypatch):
    source=tmp_path/'originals';source.mkdir();rows=[row('a/one.tsv'),row('b/two.tsv'),row('three.json')]
    for r in rows:
        p=source/r['path'];p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(b'abc')
    manifest=tmp_path/'manifest.json';manifest.write_bytes(b'fixture')
    monkeypatch.setattr(m,'read_manifest',lambda *a:({'files':rows},b'fixture'))
    monkeypatch.setattr(m,'TOTAL',9);monkeypatch.setitem(m.LIMITS,'originals',(3,9,1800))
    monkeypatch.setattr(m.shutil,'disk_usage',lambda p:SimpleNamespace(free=10*1024**3))
    return source,rows,manifest,tmp_path/'staged',tmp_path/'work'


def test_final_manifest_pin_and_closed_metadata():
    assert m.MANIFEST_SHA=='70000c5c93c2c43f1e7968feb38aaebb4e7622a5f6d2ec1167191337614ef950'
    manifest,_=m.read_manifest(Path(__file__).parents[1]/'environment'/'source_manifest.json')
    assert len(manifest['files'])==131 and manifest['source_files_directory']=='.'


def test_default_plan_no_source_access(monkeypatch,capsys):
    monkeypatch.setattr(m,'read_manifest',lambda *a:pytest.fail('plan source read'))
    assert m.main([])==0
    assert json.loads(capsys.readouterr().out)['runtime_source_root']=='/app/data/emomatch'


def test_local_complete_copy_no_input_mutation(manufactured):
    source,rows,manifest,dest,work=manufactured
    before={r['path']:m.identity((source/r['path']).stat()) for r in rows}
    report=m.stage(dest,work,manifest_path=manifest,source_dir=source)
    assert report['status']=='complete' and report['requests_started']==0 and report['bytes_received']==0
    assert not (dest/'source_manifest.json').exists()
    assert {p.relative_to(dest).as_posix() for p in dest.rglob('*') if p.is_file()}=={r['path'] for r in rows}
    for r in rows:
        assert (dest/r['path']).read_bytes()==b'abc'
        assert m.identity((source/r['path']).stat())==before[r['path']]
        assert (dest/r['path']).stat().st_mode&0o777==0o444
    assert m.verify_staged(dest,manifest)=={'files':rows}


@pytest.mark.parametrize('kind',['extra','missing','symlink','directory','corrupt','size'])
def test_local_reject_before_any_original_copy(manufactured,kind):
    source,rows,manifest,dest,work=manufactured
    if kind=='extra':(source/'extra').write_bytes(b'x')
    elif kind=='missing':(source/'three.json').unlink()
    elif kind=='symlink':(source/'link').symlink_to(source/'three.json')
    elif kind=='directory':(source/'extra').mkdir()
    elif kind=='corrupt':(source/'three.json').write_bytes(b'bad')
    elif kind=='size':(source/'three.json').write_bytes(b'longer')
    with pytest.raises(m.SourceError):m.stage(dest,work,manifest_path=manifest,source_dir=source)
    assert not dest.exists()
    assert json.loads((work/'result.json').read_text())['status']=='failed_preserved'


@pytest.mark.parametrize('kind',['dest_source','dest_inside_source','work_source','work_inside_source','same_dest_work','dest_exists','work_exists','link','dotdot'])
def test_safe_overlap_preservation(manufactured,kind):
    source,rows,manifest,dest,work=manufactured
    if kind=='dest_source':dest=source
    elif kind=='dest_inside_source':dest=source/'child'
    elif kind=='work_source':work=source
    elif kind=='work_inside_source':work=source/'child'
    elif kind=='same_dest_work':work=dest
    elif kind=='dest_exists':dest.mkdir();(dest/'keep').write_bytes(b'keep')
    elif kind=='work_exists':work.mkdir()
    elif kind=='link':dest.symlink_to(source/'missing')
    elif kind=='dotdot':dest=str(source/'link')+'/../outside'
    with pytest.raises(m.SourceError):m.stage(dest,work,manifest_path=manifest,source_dir=source)
    assert (source/'three.json').read_bytes()==b'abc' and not (source/'child').exists()


def test_verify_is_read_only(manufactured):
    source,rows,manifest,dest,work=manufactured
    before={p.relative_to(source).as_posix():m.identity(p.stat()) for p in source.rglob('*')}
    assert m.verify_staged(source,manifest)['files']==rows
    after={p.relative_to(source).as_posix():m.identity(p.stat()) for p in source.rglob('*')}
    assert before==after and not dest.exists() and not work.exists()


def test_source_change_between_precheck_copy_fails(manufactured):
    source,rows,_,dest,_=manufactured;identities=m.authenticate_all(source,rows);dest.mkdir()
    (source/rows[-1]['path']).write_bytes(b'bad')
    # A same-tick rewrite may retain tmpfs stat timestamps; content hashing must
    # still reject it even when the earlier inode/time identity check cannot.
    with pytest.raises(m.SourceError,match='source_changed|source_sha256'):m.copy_all(source,dest,rows,identities)
    assert not (dest/rows[-1]['path']).exists()
    assert (dest/(rows[-1]['path']+'.partial')).exists()


class Response(io.BytesIO):
    def __init__(self,r,payload=b'abc'):
        super().__init__(payload);self.status=200;self.url=r['url'];self.headers=Message()
        self.headers['Content-Length']=str(r['size_bytes']);self.headers['Content-Type']='text/plain'
    def geturl(self):return self.url
    def read1(self,n):return super().read(n)


@pytest.mark.parametrize('defect',['length','encoding','type','url','truncated','oversized','hash','none'])
def test_production_transport_directly(manufactured,defect):
    source,rows,manifest,dest,work=manufactured
    class Opener:
        def open(self,request,timeout):
            r=next(r for r in rows if r['url']==request.full_url)
            response=Response(r,b'ab' if defect=='truncated' else b'abcd' if defect=='oversized' else b'bad' if defect=='hash' else b'abc')
            if defect=='length':response.headers['Content-Length']='3'
            elif defect=='encoding':response.headers['Content-Encoding']='gzip'
            elif defect=='type':response.headers.replace_header('Content-Type','text/html')
            elif defect=='url':response.url='https://evil.example'
            return response
    if defect=='none':
        report=m.stage(dest,work,manifest_path=manifest,opener_factory=Opener)
        assert report['status']=='complete' and report['bytes_received']==9
    else:
        with pytest.raises(m.SourceError):m.stage(dest,work,manifest_path=manifest,opener_factory=Opener)
        report=json.loads((work/'result.json').read_text());assert report['status']=='failed_preserved'
        assert report['requests_started']<=2


def test_full_measured_sha_required(tmp_path,monkeypatch):
    original=json.loads((Path(__file__).parents[1]/'environment'/'source_manifest.json').read_bytes())
    original['files'][0]['sha256']=None
    p=tmp_path/'manifest.json';raw=json.dumps(original).encode();p.write_bytes(raw)
    monkeypatch.setattr(m,'MANIFEST_SHA',m.sha(raw))
    with pytest.raises(m.SourceError,match='all131_measured_sha_required'):m.read_manifest(p)
